                # Ensure chained divisions are treated as left-associative.
                # a/b/c becomes a/(b*c). If the right hand side has multiple units,
                # multiply them into the denominator.
                rhs = p[3]
                try:
                    bases, powers = rhs.bases, rhs.powers
                except Exception:
                    p[0] = p[1] / rhs
                else:
                    denom = core.dimensionless_unscaled
                    for base, power in zip(bases, powers):
                        if power:
                            denom = denom * (base ** abs(int(power)))
                    p[0] = p[1] / denom

